import{_ as o,o as t,c as r,a5 as d}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"完整摸了一遍。这个组件比 SLTP 体系本身的工程含量更框架级，我给你客观评估和放法。","description":"完整摸了一遍。这个组件比 SLTP 体系本身的工程含量更\\"框架级\\"，我给你客观评估和放法。 一、客观评估：值不值得写 结论：值得写，且属于上等亮点。 给你 3 条客观理由： 1. 架构思维是\\"框架级\\"而不是\\"业务级\\" ： 严格四层分层 core (纯 TS pipeline +。","frontmatter":{"title":"完整摸了一遍。这个组件比 SLTP 体系本身的工程含量更框架级，我给你客观评估和放法。","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","求职准备"],"description":"完整摸了一遍。这个组件比 SLTP 体系本身的工程含量更\\"框架级\\"，我给你客观评估和放法。 一、客观评估：值不值得写 结论：值得写，且属于上等亮点。 给你 3 条客观理由： 1. 架构思维是\\"框架级\\"而不是\\"业务级\\" ： 严格四层分层 core (纯 TS pipeline +。","sidebarWeight":6,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/简历设计/Max 亮点/完整摸了一遍。这个组件比 SLTP 体系本身的工程含量更框架级，我给你客观评估和放法。.md"},"headers":[],"relativePath":"posts/前端面试与实战/05-求职准备/Max 亮点/完整摸了一遍。这个组件比 SLTP 体系本身的工程含量更框架级，我给你客观评估和放法。.md","filePath":"posts/前端面试与实战/05-求职准备/Max 亮点/完整摸了一遍。这个组件比 SLTP 体系本身的工程含量更框架级，我给你客观评估和放法。.md"}'),n={name:"posts/前端面试与实战/05-求职准备/Max 亮点/完整摸了一遍。这个组件比 SLTP 体系本身的工程含量更框架级，我给你客观评估和放法。.md"};function l(i,e,c,s,a,p){return t(),r("div",null,[...e[0]||(e[0]=[d('<div><h1 id="完整摸了一遍。这个组件比-sltp-体系本身的工程含量更框架级-我给你客观评估和放法。" tabindex="-1">完整摸了一遍。这个组件比 SLTP 体系本身的工程含量更框架级，我给你客观评估和放法。 <a class="header-anchor" href="#完整摸了一遍。这个组件比-sltp-体系本身的工程含量更框架级-我给你客观评估和放法。" aria-label="Permalink to &quot;完整摸了一遍。这个组件比 SLTP 体系本身的工程含量更框架级，我给你客观评估和放法。&quot;">​</a></h1><blockquote><p>本节目标：理解“完整摸了一遍。这个组件比 SLTP 体系本身的工程含量更框架级，我给你客观评估和放法。”的核心思路，并能把它用于实际开发或面试表达。 完整摸了一遍。这个组件比 SLTP 体系本身的工程含量更&quot;框架级&quot;，我给你客观评估和放法。</p></blockquote><h2 id="一、客观评估-值不值得写" tabindex="-1">一、客观评估：值不值得写 <a class="header-anchor" href="#一、客观评估-值不值得写" aria-label="Permalink to &quot;一、客观评估：值不值得写&quot;">​</a></h2><p><strong>结论：值得写，且属于上等亮点。</strong> 给你 3 条客观理由：</p><ol><li><strong>架构思维是&quot;框架级&quot;而不是&quot;业务级&quot;</strong>：</li></ol><ul><li>严格四层分层 <code>core (纯 TS pipeline + utils) → composables (Vue 桥接) → strategy (4 种 locale 策略) → component (headless + 默认皮肤)</code>；</li><li>用了 <strong>Headless Component + Strategy + Pipeline</strong> 三种设计模式叠加；</li><li><strong>三段式 pipeline</strong> 把&quot;初始化态 / 输入态 / 操作态&quot;分相处理（<code>applyInit / applyInput / applyOperation</code>）—— 这是一般 number input 组件最容易翻车的点（输入 <code>1.0</code> 立刻被补成 <code>1</code>、光标乱跳），这套设计专门解决；</li><li>这种分层只在框架/UI 库里能见到，业务前端能写出来的人不多。</li></ul><ol start="2"><li><strong>金融场景独到细节，全部能讲故事</strong>：</li></ol><ul><li><strong>显示层禁止四舍五入</strong>，强制用 Decimal <code>trunc()</code> 向零截断 —— 报价不会被偷偷&quot;涨上去&quot;；</li><li><strong>从 <code>step</code> 反推最小显示位数</strong>（含科学计数法 <code>1e-5</code> 解析）—— 解决 JS <code>1.00010</code> 被丢成 <code>1.0001</code> 但金融 step=0.00001 必须显示 5 位的坑；</li><li><strong><code>presentation: auto</code></strong> 双态展示：聚焦走 <code>leanTyping</code>（不补尾随零，保护 <code>1.0</code> <code>0.</code>）/失焦走 <code>pretty</code>（按 step 补零、按 locale 千分号）；</li><li><strong>4 种 locale 策略</strong>：<code>intl</code> 3 位分组 / <code>cjk4</code> 4 位分组（万/亿）/ <code>currency</code> 货币 / <code>leanTyping</code>，按 <code>Intl.NumberFormat</code> 反推每个 locale 的 <code>decimalChar / groupChar</code> 并缓存；</li><li><strong>7 种舍入模式</strong>（half-up/down/even、up/down/ceil/floor/trunc）；</li><li><strong>全程 Decimal.js</strong>：step 累加、model 同步用 <code>lessThan(1e-10)</code> 容差比较防循环、加速因子 <code>product</code> 模式连乘；</li><li><strong>IME 合成保护</strong> + <strong>滚轮 throttle 16ms</strong> + <strong>长按连发</strong>（300ms 判定 + 100ms 间隔）+ <strong>修饰键加速</strong>（shift×10 / ctrl×5 / alt×0.1，max/product 两种组合）+ <strong>触屏支持</strong>；</li><li><strong>受控 / 非受控双模</strong>：<code>isControlled = modelValue !== undefined</code>，非受控首次&quot;初始提升&quot;，失焦 <code>finalize()</code> 强制规范化。</li></ul><ol start="3"><li><strong>复用面真实可考证</strong>：</li></ol><ul><li>是 <strong>SLTP 体系（亮点 2）的底座</strong>；</li><li>直接复用：<code>LimitPriceInput.vue</code>（限价单输入）、<code>PriceEditor.vue</code>（订单改价）、<code>CloseTabPane.vue</code>（平仓数量）、<code>SLTPField.vue</code>（止盈止损）—— <strong>4+ 个金融关键输入入口共用同一个 headless</strong>；</li><li>错误码与 i18n 解耦：内核 emit <code>&#39;inValid&#39; / &#39;lessThanMin&#39; / &#39;greaterThanMax&#39; / &#39;negativeNotAllowed&#39;</code> 等 key，皮肤层做 18 语言翻译，业务可以无缝换皮。</li></ul><p><strong>风险提示</strong>：<code>core/pipeline.ts</code> 里 <code>applyInit</code> 还有几处 <code>console.warn</code> 残留（line 25/30/37/40），看起来像开发期日志没清。简历不会暴露这个，但<strong>面试 deep-dive 时如果被追问到代码细节，最好提前清掉，或者面试时主动说&quot;目前在清理 verbose log&quot;</strong>。</p><hr><h2 id="二、怎么放进简历-最佳放法" tabindex="-1">二、怎么放进简历（最佳放法） <a class="header-anchor" href="#二、怎么放进简历-最佳放法" aria-label="Permalink to &quot;二、怎么放进简历（最佳放法）&quot;">​</a></h2><p><strong>不要让它和 SLTP 那条互相抢戏。</strong> 我建议两条并排，分工：</p><ul><li><strong>SLTP 那条</strong>（亮点 2）：强调&quot;业务规则编排 + 4 入口共用一份控制器&quot;；</li><li><strong>NumericInput 这条</strong>（新增亮点 / 独立 Top）：强调&quot;框架级工程能力 + 金融精度细节 + 复用底座&quot;。</li></ul><p>这样面试官看完会形成一个清晰认知：<strong>你既能做业务规则的复杂封装，也能下沉做基建组件</strong>——这正是&quot;前端技术负责人&quot;的画像。</p><p>排在 Top 8 的位置建议放在 <strong>第 6 位</strong>（紧挨 Worker 化那条），这样上半段基建 / 下半段业务，节奏好。</p><hr><h2 id="三、可以直接放进简历的两段" tabindex="-1">三、可以直接放进简历的两段 <a class="header-anchor" href="#三、可以直接放进简历的两段" aria-label="Permalink to &quot;三、可以直接放进简历的两段&quot;">​</a></h2><h3 id="_1-追加到「技术亮点扫描」-第-14-条" tabindex="-1">1）追加到「技术亮点扫描」（第 14 条） <a class="header-anchor" href="#_1-追加到「技术亮点扫描」-第-14-条" aria-label="Permalink to &quot;1）追加到「技术亮点扫描」（第 14 条）&quot;">​</a></h3><p>【技术亮点 14】Headless 数值输入框：分层 pipeline + 多策略 + 金融精度</p><ul><li><strong>文件位置</strong>：</li><li><code>src/components/numeric-input/core/{core,pipeline,types,constants}.ts</code>、<code>utils/{number,format}.ts</code></li><li><code>src/components/numeric-input/composables/{useNumericCore,useNumericInteractions,useSplitOptions,useModelSync}.ts</code></li><li><code>src/components/numeric-input/components/{NumericInputHeadless,NumericInput}.vue</code></li><li><code>src/components/numeric-input/numberStrategy.ts</code></li><li><strong>实现内容</strong>：</li><li>严格四层分层 —— <code>core</code>（纯 TS pipeline + utils）→ <code>composables</code>（Vue 桥接）→ <code>strategy</code>（4 种 locale 策略）→ <code>component</code>（headless + 默认皮肤），框架级工程能力；</li><li><strong>三段式 pipeline</strong> 把&quot;初始化态 / 输入态 / 操作态&quot;完全分相：<code>applyInit</code> 走 clamp + 步长对齐 + 精度舍入；<code>applyInput</code> 保留用户原始字符串只做校验、不格式化（避免光标跳/补零干扰输入）；<code>applyOperation</code> 在 spin/wheel/keyboard/setModel 时统一规范化；</li><li><strong>双态展示</strong>：<code>presentation: auto/typing/pretty</code>，聚焦用 <code>createLeanTypingStrategy</code>（不从 step 推断补零，保护 <code>1.0</code> <code>0.</code>），失焦用 <code>createIntlNumberStrategy / cjk4 / currency</code>（按 step 推断补尾随零、按 locale 千分号或 CJK 4 位分组）；</li><li><strong>4 种 locale 策略</strong>：<code>Intl.NumberFormat</code> 反推每个 locale 的 <code>decimalChar / groupChar</code> 并缓存；</li><li><strong>7 种舍入模式</strong>（half-up / half-down / half-even / up / down / ceil / floor / trunc），金融场景默认显示层 <code>trunc</code> 向零截断、显式禁用四舍五入，避免报价被偷偷&quot;涨上去&quot;；</li><li><strong>从 step 反推最小显示位数</strong>（含科学计数法 <code>1e-5</code> 字符串解析），解决 JS <code>1.00010</code> 被丢成 <code>1.0001</code> 但金融 5 位 digits 必须保留的坑；</li><li><strong>全程 Decimal.js</strong>：step 累加、model 同步用 <code>lessThan(1e-10)</code> 容差比较防循环更新、加速因子 <code>product</code> 模式连乘；</li><li><strong>完备交互</strong>：滚轮 throttle 16ms、键盘 ArrowUp/Down + PageUp/Down + 修饰键加速（shift×10 / ctrl×5 / alt×0.1，max/product 双组合模式）、长按连发（300ms 长按判定 + 100ms 间隔）、IME 合成保护、触屏 touchstart/touchend；</li><li><strong>受控 / 非受控双模</strong>：<code>isControlled = modelValue !== undefined</code>，非受控首次&quot;初始提升&quot;一次 model，失焦 <code>finalize()</code> 强制规范化；</li><li><strong>错误码与 i18n 解耦</strong>：内核 emit <code>&#39;inValid&#39; / &#39;lessThanMin&#39; / &#39;greaterThanMax&#39; / &#39;negativeNotAllowed&#39;</code>，皮肤层挂 18 语言翻译，业务可换皮零成本；</li><li><strong>复用面</strong>：SLTPField、LimitPriceInput、PriceEditor、CloseTabPane 等 4+ 个金融关键输入入口共用同一份 headless。</li><li><strong>技术栈</strong>：Vue 3 Composition API、<code>defineModel</code>、Headless Component / Strategy / Pipeline 三种模式、Decimal.js、<code>Intl.NumberFormat</code>、<code>useThrottleFn</code>、TypeScript。</li><li><strong>业务价值</strong>：所有金融数值输入（价格、数量、止盈止损、限价、改价、平仓等）共用一套精度无误差、locale 自适应、IME/触屏/键盘/滚轮全场景可控的输入原语。新增金融输入场景从&quot;造一个 number input&quot;降级为&quot;挑配置策略&quot;。</li><li><strong>简历建议表述</strong>： &gt; 自研 Headless 数值输入框：以「core pipeline + 4 种 locale 策略 + Vue composable 桥接 + 默认皮肤」四层分层封装，三段式 pipeline 分相处理初始化/输入/操作，聚焦/失焦双态展示策略，全程 Decimal.js 精算并显式禁用显示层四舍五入；支持 7 种舍入模式、修饰键加速、长按连发、IME 保护、受控/非受控双模、错误码 i18n 解耦；<strong>作为 SLTPField / LimitPriceInput / PriceEditor / CloseTabPane 等 4+ 个金融关键输入入口的统一底座</strong>，新增金融输入场景从写组件降级为选策略。</li></ul><hr><h3 id="_2-插入「核心简历亮点」第-6-位-其余条目顺延" tabindex="-1">2）插入「核心简历亮点」第 6 位（其余条目顺延） <a class="header-anchor" href="#_2-插入「核心简历亮点」第-6-位-其余条目顺延" aria-label="Permalink to &quot;2）插入「核心简历亮点」第 6 位（其余条目顺延）&quot;">​</a></h3><p>&gt; <strong>【框架级 Headless 数值输入底座】</strong> &gt; 自研以「core pipeline + 4 种 locale 策略 + composable 桥接 + 默认皮肤」四层分层的 Headless Numeric Input：三段式 pipeline 把初始化/输入/操作三相分离（解决传统 number input &quot;输入 <code>1.0</code> 即被补 <code>1</code>&quot;等顽疾），聚焦/失焦双态展示策略，<strong>显示层显式禁用四舍五入并用 Decimal.js trunc 截断</strong>（防金融报价被偷涨）、按 step 反推最小小数位（兜住 JS <code>1.00010</code> 被丢精度）、IME / 触屏 / 滚轮 / 修饰键加速 / 长按连发 / 受控-非受控双模全场景可控；作为 <strong>SLTPField、LimitPriceInput、PriceEditor、CloseTabPane</strong> 等 4+ 个金融输入入口的统一底座。</p><hr><h2 id="四、合并后-top-8-的最终顺序-仅作建议" tabindex="-1">四、合并后 Top 8 的最终顺序（仅作建议） <a class="header-anchor" href="#四、合并后-top-8-的最终顺序-仅作建议" aria-label="Permalink to &quot;四、合并后 Top 8 的最终顺序（仅作建议）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>亮点</th><th>性质</th></tr></thead><tbody><tr><td>1</td><td>实时行情列表 — Worker + rAF + 虚拟化</td><td>性能 / 实时</td></tr><tr><td>2</td><td>自研 SL/TP 输入体系</td><td>业务深度</td></tr><tr><td>3</td><td>交易 WebSocket 全链路</td><td>通信 / 自愈</td></tr><tr><td>4</td><td>K 线自定义 Datafeed</td><td>图表 / 实时</td></tr><tr><td>5</td><td>金融级 MFA 编排框架</td><td>安全 / 编排</td></tr><tr><td>6</td><td><strong>Headless 数值输入底座</strong>（新加） ⭐</td><td><strong>框架基建</strong></td></tr><tr><td>7</td><td>独立 Web Worker 化的计算密集模块</td><td>性能</td></tr><tr><td>8</td><td>HTTP 中台层 + 跨流程编排 + i18n + 业务规则落地</td><td>工程基建</td></tr></tbody></table><p>&gt; <strong>写法建议</strong>：1~5 当&quot;技术深度题&quot;；6~7 当&quot;工程基建&quot;；8 当&quot;业务深度&quot;。 &gt; 每条都带量化（4 入口 / 4 策略 / 7 舍入模式 / 18 语言 / 20fps / 数千品种 等），与代码点一一对应，被追问不会慌。</p><hr><p>需要我把第 6 条和第 2 条的&quot;协同关系&quot;再写一段过渡话术（用于面试自我介绍中口头表达&quot;我先做了 NumericInput 这个底座，再用它和 4 个 composable 搭起 SL/TP 这一层业务积木&quot;）吗？</p></div>',1)])])}const m=o(n,[["render",l]]);export{g as __pageData,m as default};
